                      <div className={`w-20 h-20  overflow-hidden border-4 border-transparent t.color p-0.5 shadow-lg`}>
                        <div className="w-full h-full rounded-xl overflow-hidden">
                          <Image
                            src={t.image}
                            alt={t.name}
                            width={80}
                            height={80}
                            className="w-full h-full object-cover"
                          />
